import pytest
import json
from pathlib import Path
from validator import SwaggerSchemaValidator

# Load the OpenAPI specification for validation
swagger_validator = SwaggerSchemaValidator('api.json')

# Load test data from JSON file
_here = Path(__file__).resolve().parent
_endpoint_data_path = _here / 'user_username.json'
with open(_endpoint_data_path, 'r') as f:
    _ENDPOINT_DATA = json.load(f)

# Reusable parametrize args
_PARAM_CASES = _ENDPOINT_DATA
_PARAM_IDS = [f"Scenario: {case['scenario']}" for case in _ENDPOINT_DATA]

@pytest.mark.parametrize("scenario_case", _PARAM_CASES, ids=_PARAM_IDS)
def test_update_user(api_client, config_test_data, scenario_case):
    """
    Test the update user endpoint with various scenarios.
    """
    username = scenario_case.get('username', config_test_data['username'])
    endpoint = f"/user/{username}"
    headers = {'Content-Type': 'application/json'}
    
    # Prepare request data
    request_data = {
        "id": scenario_case.get('id'),
        "username": scenario_case.get('username'),
        "firstName": scenario_case.get('firstName'),
        "lastName": scenario_case.get('lastName'),
        "email": scenario_case.get('email'),
        "password": scenario_case.get('password'),
        "phone": scenario_case.get('phone'),
        "userStatus": scenario_case.get('userStatus')
    }
    
    # Remove None values to avoid sending them in the request
    request_data = {k: v for k, v in request_data.items() if v is not None}
    
    # Validate request schema
    swagger_validator.validate_json(request_data, 'User')
    
    # Make the PUT request
    response = api_client.put(endpoint, data=json.dumps(request_data), headers=headers)
    
    # Validate response status code
    expected_status_code = scenario_case['statusCode']
    assert response.status_code == expected_status_code, f"Expected {expected_status_code}, got {response.status_code}"
    
    # Validate response schema
    validation_result = swagger_validator.validate_schema_by_response(endpoint, 'put', str(response.status_code), response)
    assert validation_result['valid'], f"Response validation failed: {validation_result.get('message', '')}"

    # Additional assertions based on scenario
    if response.status_code == 200:
        response_data = response.json()
        assert response_data['username'] == request_data['username'], "Username mismatch in response"
    elif response.status_code == 400:
        assert 'error' in response.json(), "Expected error message in response"
    elif response.status_code == 404:
        assert 'error' in response.json(), "Expected error message in response"
    elif response.status_code == 500:
        pytest.skip("Skipping server error scenario")
